WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_ms_ana_story'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '哲理故事类', 'kp-ms-ana-story', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "综合分析：哲理故事类"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "一个故事，多角度发散。最忌讳钻牛角尖。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“青蛙在沸水里能跳出来，在温水里被煮死。谈谈启示。”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、发散思维法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "不要只说一个道理！高分答案必须是从不同主体、不同角度切入。"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "角度一（从温水看）：安逸的环境会消磨人的斗志，要有居安思危的忧患意识。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "角度二（从青蛙看）：自身缺乏对细微变化的敏锐感知，要保持终身学习和警惕。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "角度三（从沸水看）：突如其来的危机反而能激发巨大的潜能。"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "然后在接下来的段落里，分别对这三个角度展开论述（结合公职人员的日常工作）。"}]}]}$$ AS jsonb), NULL, '哲理故事类的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "综合分析", "哲理故事"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_ana_story", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
